INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 1, 'theory', 'Квиз: рождение JavaScript');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 0, 'Почему язык получил название JavaScript?', '["Он создан на основе Java","Его написала компания Sun","Он компилируется в байт-код Java","Это маркетинговый ход: Netscape договорилась с Sun, а к Java язык отношения не имеет"]', 3, 'Первый прототип назывался Mocha, затем LiveScript; имя JavaScript появилось в декабре 1995 года из-за популярности Java.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 1, 'Откуда в JavaScript взялись функции как значения и замыкания?', '["Из Scheme","Из языка C","Из Java","Из Python"]', 0, 'Брендана Айка пригласили, чтобы встроить в браузер Scheme; функциональные идеи остались, а синтаксис сделали похожим на Java и C.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 2, 'Что такое ECMAScript?', '["Браузер от Microsoft","Библиотека для работы с DOM","Название стандарта, по которому реализуется язык; JavaScript — торговая марка и самая известная реализация","Расширение протокола HTTP"]', 2, 'Netscape передала язык организации Ecma International; в 1997 году вышел стандарт ECMA-262, развивает его комитет TC39.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 3, 'Что сделали Gmail и Google Maps в 2004–2005 годах?', '["Заменили JavaScript на Flash","Показали, что страница может запрашивать данные в фоне без перезагрузки — подход назвали Ajax","Ввели модули в язык","Создали стандарт JSON"]', 1, 'Объект XMLHttpRequest существовал с 1999 года, но настоящую славу ему принесли именно эти приложения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 4, 'Что принёс выход Chrome с движком V8 в 2008 году?', '["Менеджер пакетов npm","Классы в языке","Отказ от стандарта ECMAScript","Компиляцию JavaScript в машинный код прямо во время работы и гонку производительности браузеров"]', 3, 'V8 превратил JavaScript из «языка для украшательств» в быстрый язык, на котором можно писать большие программы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 2, 'theory', 'Квиз: Node.js и io.js');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 0, 'Почему Райан Даль построил Node.js вокруг неблокирующего ввода-вывода?', '["Потому что JavaScript нельзя выполнять в потоках","Классические серверы тратили поток на каждое соединение, а потоки впустую ждали диск и сеть","Потому что в браузерах нет ввода-вывода","Чтобы не пользоваться движком V8"]', 1, 'Однопоточный цикл событий обслуживает тысячи медленных клиентов: операция запускается, регистрируется колбэк, управление возвращается циклу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 1, 'Что такое libuv?', '["Кроссплатформенная библиотека, которая ждёт события ОС (epoll, kqueue, IOCP) и реализует цикл событий","Менеджер пакетов Node.js","Движок JavaScript от Google","Стандарт модулей CommonJS"]', 0, 'Первоначально использовались libev и libeio; libuv появилась, чтобы поддерживать и Windows.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 2, 'Что послужило причиной форка io.js в декабре 2014 года?', '["Технический спор о том, как работает V8","Переход на язык Rust","Недовольство закрытым управлением (одна компания), редкими выпусками и устаревшим V8","Запрет использования npm"]', 2, 'Разработчики хотели открытое управление техническим комитетом, быстрые выпуски по semver и свежий V8 с новыми возможностями языка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 3, 'Чем закончилась история io.js?', '["io.js был закрыт без последствий","io.js вытеснил Node.js и сохранил своё имя","Node.js перешёл под управление Microsoft","Проекты объединились: в сентябре 2015 вышел Node.js 4.0 на кодовой базе io.js"]', 3, 'Версия прыгнула с 0.12 сразу на 4: версии 1–3 уже занял io.js. Открытое управление и регулярные выпуски стали основой Node.js.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 4, 'Как называется формат модулей, которым Node.js пользуется с ранних версий (require и module.exports)?', '["ES-модули","CommonJS","AMD","UMD"]', 1, 'require подключает файл, а module.exports отдаёт наружу нужное; ES-модули (import/export) появились позже и поддерживаются в Node.js встроенно.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 3, 'theory', 'Квиз: ES5, ES6, Babel и инструменты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 0, 'Почему между ES3 и ES5 прошло десять лет?', '["Не было желающих развивать язык","Язык был юридически заблокирован","Раскол в комитете вокруг амбициозной ES4 и необходимость поддерживать старые браузеры","Все ждали выхода Node.js"]', 2, 'ES4 отменили в 2008 году, скромные идеи (ES3.1) стали ES5; новый синтаксис нельзя было использовать, пока IE6–IE8 были распространены.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 1, 'Что принесла пятая редакция ES5 (2009)?', '["Строгий режим, объект JSON, методы массивов forEach/map/filter/reduce","Классы и модули","async/await","Стрелочные функции"]', 0, 'Классы, модули и стрелки появились только в ES2015, а async/await — в ES2017.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 2, 'Что делает Babel?', '["Сжимает изображения","Разбирает код в дерево и преобразует новый синтаксис в старый, понятный нужным браузерам","Запускает JavaScript на сервере","Заменяет npm"]', 1, 'Plugins и presets описывают преобразования; недостающие встроенные объекты дополняют полифилы core-js, а целевые браузеры задаёт browserslist.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 3, 'Какие возможности препроцессоры Sass, Less и Stylus добавили в CSS?', '["Асинхронные запросы","Типы данных","Классы","Переменные, вложенные правила, миксины и импорт файлов"]', 3, 'Сегодня часть этих возможностей (переменные, вложенность) появилась и в самом CSS.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 4, 'Что произошло в марте 2016 года с пакетом left-pad?', '["Автор удалил пакет из 11 строк из npm, и сборки по всему миру упали","Его включили в стандарт языка","Он стал частью webpack","Его заменили на Babel"]', 0, 'Инцидент показал хрупкость цепочек поставок: огромные деревья мелких зависимостей зависят друг от друга.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 4, 'theory', 'Квиз: первая программа, Node и значения');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 0, 'Что делает движок V8 с часто вызываемыми функциями?', '["Выполняет их только интерпретатором","Переводит их обратно в исходный текст","Компилирует на лету в машинный код процессора (JIT)","Сохраняет их в файл на диске"]', 2, 'Текст разбирается в дерево, затем в байт-код, а «горячие» функции компилируются прямо во время работы в машинный код.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 1, 'Что произойдёт при const user = { n: 1 }; user.n = 2;?', '["Поле изменится: const запрещает только замену самой привязки","TypeError: присваивание константе","Объект будет скопирован","user станет неизменяемым"]', 0, 'const фиксирует привязку имени к значению, а не содержимое объекта: user = {} вызовет ошибку, а user.n = 2 — нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 2, 'Чему равно typeof null?', '["\"null\"","\"undefined\"","\"number\"","\"object\""]', 3, 'Это историческая ошибка языка, которую не исправляют ради совместимости; проверять null нужно сравнением x === null.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 3, 'Почему 0.1 + 0.2 === 0.3 даёт false?', '["Из-за ошибки сложения в движке","Число одно — 64-битное дробное, и 0.1 с 0.2 в двоичном виде не точны","Потому что 0.3 — строка","Потому что оператор === сравнивает типы строк"]', 1, 'Все числа — IEEE 754 двойной точности, как double в C; десятичные дроби вроде 0.1 в двоичной системе приближённые.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 4, 'Какое выражение вернёт 0?', '["0 || 5","'''' || 0 || 5","null ?? 5","0 ?? 5"]', 3, 'Оператор ?? выбирает правый операнд только для null и undefined, поэтому 0 остаётся; || заменяет любое ложное значение, включая 0.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 5, 'theory', 'Квиз: операторы, приведение типов и сравнение');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 0, 'Чему равно ''5'' + 1 и ''5'' - 1?', '["6 и 4","''51'' и 4","''51'' и ''4''","6 и 6"]', 1, 'Если есть строка, + склеивает; минус всегда числовой оператор и приводит строку к числу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 1, 'Чему равно -7 % 3?', '["2","1","-2","-1"]', 3, 'Остаток берёт знак делимого, как в C; в Python результат был бы 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 2, 'Почему [''10'', ''9'', ''1''].sort() и [10, 9, 1].sort() дают порядок «1, 10, 9»?', '["sort по умолчанию сравнивает элементы как строки","Из-за ошибки движка","sort работает только со строками","sort сортирует по убыванию"]', 0, 'Без функции сравнения элементы приводятся к строкам и сравниваются по кодам; для чисел нужен (a, b) => a - b.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 3, 'Что вернёт 0 ?? 5, а что — 0 || 5?', '["5 и 5","0 и 0","0 и 5","5 и 0"]', 2, '?? заменяет только null и undefined, поэтому 0 сохраняется; || заменяет любое ложное значение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 4, 'Что делает выражение 0 < x < 10 при x = 15?', '["Возвращает false, как проверка диапазона","Бросает исключение","Возвращает true: (0 < 15) → true, затем true < 10","Возвращает 15"]', 2, 'Цепочка сравнений не проверяет диапазон: сначала получается булево значение, которое приводится к числу. Пишите x > 0 && x < 10.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 6, 'theory', 'Квиз: функции, область видимости и замыкания');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 0, 'Что выведет код: for (var i = 0; i < 3; i++) fns.push(() => i); затем вызов всех функций из fns?', '["0, 1, 2","undefined три раза","Ошибку ReferenceError","3, 3, 3"]', 3, 'var объявляет одну переменную на всю функцию, и все стрелки видят её после цикла, когда i равна 3. С let получилось бы 0, 1, 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 1, 'Чем отличается стрелочная функция от обычной?', '["У стрелки нет собственного this: она берёт его из окружения, где создана","Стрелка нельзя вызвать с аргументами","Стрелка всегда выполняется асинхронно","Стрелка поднимается вверх области, как объявление"]', 0, 'Стрелка не имеет своих this и arguments. Поэтому она удобна для колбэков внутри методов, но не годится как метод объекта.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 2, 'Что такое замыкание?', '["Функция, которая вызывает саму себя","Блок кода в фигурных скобках","Функция вместе с окружением, в котором она создана, — она помнит его переменные","Функция без параметров"]', 2, 'Внутренняя функция хранит ссылку на окружение, где была создана, поэтому переменные доживают до тех пор, пока жива сама функция.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 3, 'Что произойдёт при обращении к let x до строки let x = 5;?', '["Вернётся undefined","ReferenceError: переменная во «временной мёртвой зоне»","Вернётся 5","SyntaxError при загрузке файла"]', 1, 'Имя известно движку с начала блока, но до инициализации обращаться к нему нельзя. Для var вернулся бы undefined.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 4, 'Чему равен f(1, null) при function f(a, b = 5) { return [a, b]; }?', '["[1, null]","[1, 5]","[1, undefined]","TypeError"]', 0, 'Значение по умолчанию подставляется только для undefined; null остаётся как есть.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 7, 'theory', 'Квиз: объекты, массивы и коллекции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 0, 'Что произойдёт с оригиналом при const b = { ...a }; b.inner.x = 5; если inner — вложенный объект?', '["Оригинал тоже изменится: вложенный объект общий для обеих копий","Ничего: копия полностью независима","Будет ошибка TypeError","Изменится только b.inner"]', 0, 'Оператор ... делает поверхностную копию: ссылка на inner копируется, а не сам объект. Для глубокой копии нужен structuredClone.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 1, 'Чему равно [10, 9, 1].sort()?', '["[1, 9, 10]","[10, 9, 1]","[1, 10, 9]","[9, 10, 1]"]', 2, 'Без функции сравнения элементы приводятся к строкам и сравниваются по кодам: «1» < «10» < «9». Для чисел нужен (a, b) => a - b.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 2, 'Когда Map лучше обычного объекта?', '["Когда ключи — только короткие строки","Когда данные нужно передать по сети как JSON","Никогда: объект всегда быстрее","Когда нужны произвольные ключи (числа, объекты), порядок вставки и нет лишних унаследованных полей"]', 3, 'Map принимает любые ключи, помнит порядок вставки и не имеет полей вроде constructor; но JSON.stringify для Map даёт {}.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 3, 'Как получить массив без повторов [1, 2, 3] из [1, 2, 2, 3, 1]?', '["arr.unique()","[...new Set(arr)]","arr.filter(Set)","Object.keys(arr)"]', 1, 'Set хранит уникальные значения, а оператор ... разворачивает его обратно в массив с сохранением порядка первого появления.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 4, 'Что произойдёт с функцией и undefined в поле при JSON.stringify({ f() {}, u: undefined, n: 1 })?', '["Они превратятся в null","Вызовется ошибка","Они будут пропущены: получится {\"n\":1}","Они превратятся в строки"]', 2, 'Функции, undefined и символы пропускаются в объектах (а в массивах становятся null); NaN и Infinity превращаются в null.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 8, 'theory', 'Квиз: классы, прототипы и итераторы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 0, 'Что делает движок, когда поле не найдено в самом объекте?', '["Сразу возвращает undefined","Бросает ReferenceError","Ищет его по цепочке прототипов вверх, пока не встретит null","Копирует поле из глобального объекта"]', 2, 'Каждый объект ссылается на прототип; поиск идёт по цепочке до null, поэтому у любого объекта находится toString из Object.prototype.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 1, 'Что вернёт typeof для класса, объявленного через class Point {}?', '["''class''","''function''","''object''","''prototype''"]', 1, 'Класс — это функция-конструктор с синтаксическим сахаром; вызвать его без new нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 2, 'Что произойдёт при обращении к полю #balance вне класса (obj.#balance)?', '["Синтаксическая ошибка: приватное поле недоступно снаружи","Вернётся undefined","Вернётся значение поля","Поле будет создано заново"]', 0, 'Имена с решёткой — настоящая приватность: к ним нельзя обратиться снаружи, даже через квадратные скобки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 3, 'Когда в конструкторе дочернего класса нужно вызывать super()?', '["После всех обращений к this","Только если у родителя есть статические методы","Никогда: движок вызывает его сам","До первого обращения к this"]', 3, 'Объект создаёт родительский конструктор: до super() this ещё не существует, и обращение к нему даёт ReferenceError.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 4, 'Какой метод должен быть у объекта, чтобы его можно было использовать в for…of?', '["forEach()","Метод с ключом Symbol.iterator, возвращающий итератор","next() на самом объекте","Свойство length"]', 1, 'Протокол итерации: [Symbol.iterator]() возвращает итератор с методом next(), дающим { value, done }. Генераторы пишут такие методы короче.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 9, 'theory', 'Квиз: модули и ошибки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 0, 'Что означает «живая привязка» у импорта в ES-модулях?', '["Модуль копирует значение при импорте","Импортёр видит изменения экспортируемой переменной, но сам менять её не может","Импорт можно перезаписать","Модуль выполняется при каждом импорте заново"]', 1, 'Привязка читается каждый раз заново: если модуль изменил экспортируемую переменную, все импортёры увидят новое значение; присвоить импортированному имени нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 1, 'Чем require в CommonJS принципиально отличается от import в ES-модулях?', '["require синхронный и может вызываться в любом месте кода","require работает только в браузере","require загружает код асинхронно","Между ними нет разницы"]', 0, 'require читает и выполняет файл синхронно, возвращая exports; import статический, поднимается наверх, а для условной загрузки есть import().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 2, 'Для чего нужен блок finally?', '["Он выполняется только при отсутствии ошибки","Он заменяет catch","Он выполняется всегда, в том числе при return и исключении, — там освобождают ресурсы","Он повторяет операцию"]', 2, 'finally срабатывает при любом выходе из try: нормальном, через return или через исключение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 3, 'Для чего служит поле cause у Error?', '["Хранит стек вызовов","Задаёт код возврата процесса","Ограничивает число повторов","Позволяет обернуть исходную ошибку в более осмысленную, не теряя первопричины"]', 3, 'new Error(''не удалось сохранить'', { cause: err }) сохраняет цепочку: в логе видно, что «вызвало» верхнюю ошибку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 4, 'Какие операции можно безопасно повторять после сбоя?', '["Любые","Только идемпотентные: повтор которых не вредит, например чтение","Только записи в базу","Никакие"]', 1, 'Повтор списания денег удвоит платёж, а повтор чтения безопасен; число попыток ограничивают, паузу увеличивают экспоненциально с jitter.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 10, 'theory', 'Квиз: промисы и async/await');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 0, 'В каком порядке выведутся строки: setTimeout(log(''T''), 0); Promise.resolve().then(log(''P'')); log(''S'')?', '["T, P, S","S, P, T","S, T, P","P, S, T"]', 1, 'Сначала синхронный код (S), затем микрозадачи — обработчики промисов (P), и только потом таймеры (T).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 1, 'Чем Promise.allSettled отличается от Promise.all?', '["allSettled быстрее","allSettled запускает промисы по очереди","allSettled всегда дожидается всех и сообщает о каждом исходе, а all отклоняется при первой ошибке","Между ними нет разницы"]', 2, 'allSettled возвращает массив объектов { status, value | reason }, поэтому одна неудача не скрывает результатов остальных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 2, 'Почему await внутри items.forEach(async x => …) не дожидается завершения всех операций?', '["forEach не умеет ждать: он вызывает функции и сразу возвращается, а возвращённые промисы игнорирует","Потому что await работает только в циклах for","Потому что массив пуст","Из-за строгого режима"]', 0, 'Для последовательного ожидания используют for…of с await, а для параллельного — Promise.all(items.map(…)).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 3, 'Как правильно «отменить» запрос fetch?', '["Вызвать promise.cancel()","Присвоить промис в null","Использовать setTimeout","Передать в fetch signal от AbortController и вызвать abort()"]', 3, 'Промис сам не отменяется; fetch слушает сигнал и отклоняется с AbortError, свои операции должны подписываться на событие abort.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 4, 'Что вернёт async-функция, в которой выполнен return 42?', '["Число 42","Промис, выполненный значением 42","undefined","Объект Error"]', 1, 'async-функция всегда возвращает промис: значение становится результатом, а исключение — причиной отклонения.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 11, 'theory', 'Квиз: функциональное программирование');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 0, 'Какая из функций чистая?', '["x => x + Math.random()","(a, b) => a + b","arr => arr.sort()","() => Date.now()"]', 1, 'Чистая функция зависит только от аргументов и ничего не меняет: sort() меняет массив на месте, остальные читают скрытое состояние.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 1, 'Почему const не делает массив неизменяемым?', '["Потому что const действует только на числа","Потому что в массивах нет методов","const запрещён в модулях","const запрещает лишь замену привязки: содержимое массива можно менять через push и другие методы"]', 3, 'Для неизменяемости нужно создавать копии ([...a, x]) и пользоваться методами toSorted, with, map и filter, а Object.freeze помогает ловить случайные правки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 2, 'В чём разница между compose(f, g) и pipe(g, f)?', '["Никакой: оба применяют сначала g, затем f; отличается лишь порядок записи","Результат разный","compose асинхронный","pipe работает только с числами"]', 0, 'compose записывают справа налево, как в математике, pipe — слева направо, как читают текст.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 3, 'Для чего в рекурсии применяют батут (trampoline)?', '["Чтобы ускорить вычисления в два раза","Чтобы кэшировать результаты","Чтобы не наращивать стек вызовов: вместо рекурсивного вызова возвращается функция-шаг, а цикл вызывает её","Чтобы вызывать функции параллельно"]', 2, 'В большинстве движков нет оптимизации хвостовых вызовов, и глубокая рекурсия падает с RangeError; батут превращает её в цикл.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 4, 'Что гарантирует закон функтора «map(x => x) ничего не меняет»?', '["map всегда возвращает число","map всегда мутирует исходный массив","map выполняется лениво","Преобразование внутри контейнера не меняет его структуру: тождественное отображение возвращает эквивалентный контейнер"]', 3, 'Вместе со вторым законом (map композиции равен композиции map) это позволяет безопасно рефакторить цепочки map.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 12, 'theory', 'Квиз: библиотеки и приёмы ФП');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 0, 'Как работает Immer?', '["Копирует весь объект при каждом вызове","Замораживает объект и запрещает изменения","Даёт прокси-черновик: вы меняете его, а библиотека строит новое состояние, копируя только затронутые узлы","Хранит данные в базе"]', 2, 'produce(state, draft => …) записывает изменения черновика и возвращает новое неизменяемое значение; если изменений нет — возвращается исходная ссылка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 1, 'Что такое линза?', '["Пара геттера и сеттера, сфокусированная на части структуры; линзы можно композировать","Функция для увеличения интерфейса","Тип данных для чисел","Метод массива"]', 0, 'view читает часть, set заменяет её, over применяет функцию; линза на адрес и линза на город склеиваются в линзу на город в адресе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 2, 'В чём состоит идея трансдьюсеров?', '["Ускорить сеть","Преобразование применяется к редьюсеру, поэтому цепочку шагов можно выполнить за один проход без промежуточных массивов","Заменить промисы","Хранить данные в кэше"]', 1, 'mapT(f) принимает редьюсер и возвращает редьюсер, который применяет f перед накоплением; шаги склеиваются обычной композицией.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 3, 'Для чего в RxJS нужен switchMap?', '["Для переключения тем","Для объединения всех потоков параллельно","Для синхронного чтения","Для каждого значения запускает внутренний поток и отменяет предыдущий — например, устаревший поисковый запрос"]', 3, 'mergeMap запускает все внутренние потоки параллельно, concatMap — по очереди, а switchMap оставляет только последний.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 4, 'Чем Validation отличается от Either?', '["Ничем","Validation работает только с числами","Validation накапливает все ошибки, а Either останавливается на первой","Validation — асинхронный"]', 2, 'Для проверки формы нужно показать пользователю все ошибки сразу, поэтому ошибки собираются в список.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 13, 'theory', 'Квиз: браузер изнутри');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 0, 'В каком порядке выполнится: setTimeout(A, 0); Promise.resolve().then(B); синхронный C?', '["A, B, C","C, A, B","C, B, A","B, C, A"]', 2, 'Сначала синхронный код (C), затем очередь микрозадач (B), и лишь потом следующая задача — таймер (A).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 1, 'Какие свойства дешевле всего анимировать?', '["width и height","transform и opacity — часто хватает одной композиции","margin и padding","font-size"]', 1, 'width и margin вызывают раскладку и отрисовку, а transform и opacity обрабатываются на этапе композиции на GPU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 2, 'Что произойдёт, если одна задача выполняется 300 мс?', '["Страница не отреагирует на клик и пропустит кадры, пока задача не закончится","Ничего: браузер многопоточный","Задача будет прервана","Таймер сработает раньше"]', 0, 'Задачи не прерываются; главный поток один, поэтому долгие задачи делят на куски (до 50 мс) и отдают управление циклу событий.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 3, 'Чем отличаются defer и async у <script>?', '["async всегда быстрее","defer блокирует разбор HTML","defer выполняется после разбора по порядку, async — как только скачался","Между ними нет разницы"]', 2, 'Обычный скрипт останавливает разбор, defer и async — нет; модули (type=module) ведут себя как defer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 13, 4, 'Зачем нужны Web Workers?', '["Чтобы обращаться к DOM из другого потока","Чтобы выполнять тяжёлые вычисления в отдельном потоке со своим циклом событий, не блокируя интерфейс","Чтобы ускорить сеть","Чтобы хранить cookie"]', 1, 'У воркера нет доступа к DOM; он общается с главным потоком сообщениями через postMessage, данные копируются структурным клонированием.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 14, 'theory', 'Квиз: дерево DOM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 0, 'Чем отличаются children и childNodes?', '["Ничем","children — только элементы, childNodes — все узлы, включая текст и комментарии","childNodes — только элементы","children включает атрибуты"]', 1, 'Пробелы между тегами — текстовые узлы, поэтому первый узел из childNodes часто оказывается текстом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 1, 'Как безопасно вставить пользовательский ввод на страницу?', '["el.textContent = input","el.innerHTML = input","document.write(input)","eval(input)"]', 0, 'textContent вставляет обычный текст: угловые скобки не превращаются в теги, поэтому внедрить скрипт нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 2, 'Что вернёт element.closest(''form'')?', '["Первого потомка-формы","Все формы документа","Следующего соседа","Ближайшего предка (включая сам элемент), подходящего под селектор, или null"]', 3, 'closest поднимается вверх по предкам; он основа делегирования событий.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 3, 'Почему <button disabled="false"> всё равно отключена?', '["Из-за ошибки браузера","Потому что false — строка «true»","Булевы атрибуты работают по наличию, а не по значению","Потому что disabled — свойство стиля"]', 2, 'Включить кнопку можно, установив свойство btn.disabled = false или удалив атрибут.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 14, 4, 'Чем querySelectorAll отличается от getElementsByClassName?', '["querySelectorAll быстрее всегда","Результат querySelectorAll — статический снимок, а getElementsByClassName — живая коллекция","Оба живые","Оба возвращают один элемент"]', 1, 'Живая коллекция обновляется при изменении дерева, поэтому её лучше превратить в массив перед обходом.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 15, 'theory', 'Квиз: CSS для программиста');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 0, 'Какой селектор специфичнее?', '[".a .b .c (0,3,0)","ul li a (0,0,3)","a:hover (0,1,1)","#id (1,0,0)"]', 3, 'Специфичность сравнивается по разрядам: один идентификатор сильнее любого числа классов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 1, 'Что делает box-sizing: border-box?', '["Включает padding и border в заданную ширину и высоту","Добавляет рамку","Убирает отступы","Включает flexbox"]', 0, 'При border-box width: 200px с padding: 20px остаётся шириной 200 пикселей — расчёты проще.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 2, 'Чем отличается grid от flex?', '["Grid — только для картинок","Flex — устаревший","Grid раскладывает в двух измерениях, flex — вдоль одной оси","Различий нет"]', 2, 'Grid удобен для каркаса страницы, flex — для содержимого компонентов; они часто работают вместе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 3, 'Почему z-index: 1000000 может не помочь?', '["Максимум — 100","Родитель создал собственный контекст наложения, и выбраться из него нельзя","z-index работает только у fixed","Нужно !important"]', 1, 'Контекст наложения создают позиционированные элементы с z-index, opacity < 1, transform и другие.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 15, 4, 'Какие свойства дешевле всего анимировать?', '["width и height","margin","top и left","transform и opacity"]', 3, 'Они часто обходятся одной композицией на GPU и не вызывают раскладку.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 16, 'theory', 'Квиз: события');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 0, 'В каком порядке событие проходит по дереву?', '["Всплытие → цель → погружение","Погружение (capture) → цель → всплытие (bubble)","Только цель","Цель → погружение"]', 1, 'Обычные слушатели срабатывают на всплытии; capture: true подписывает на погружение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 1, 'Чем отличается event.target от event.currentTarget?', '["Ничем","target — всегда document","target — где событие возникло, currentTarget — чей обработчик выполняется сейчас","currentTarget — всегда window"]', 2, 'При делегировании target — вложенный элемент, а currentTarget — контейнер, на котором висит обработчик.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 2, 'Зачем в делегировании используют closest?', '["Чтобы подняться от вложенной цели (например, значка) до нужной кнопки","Чтобы удалить элемент","Чтобы остановить всплытие","Чтобы создать копию"]', 0, 'Событие приходит от самого глубокого элемента под курсором, поэтому нужного предка находят через e.target.closest(селектор).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 3, 'Что даёт passive: true у слушателя прокрутки или касания?', '["Запрещает всплытие","Удаляет обработчик после первого вызова","Делает обработчик асинхронным","Браузеру не нужно ждать обработчика, чтобы начать прокрутку, — но preventDefault вызвать нельзя"]', 3, 'Пассивные слушатели убирают задержку прокрутки на мобильных устройствах.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 4, 'Какое свойство лучше использовать для горячих клавиш независимо от раскладки?', '["key","code","keyCode","char"]', 1, 'code описывает физическую клавишу (KeyS), key зависит от раскладки, а keyCode устарел.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 17, 'theory', 'Квиз: формы и хранилища');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 0, 'Какие поля попадут в данные формы при отправке?', '["Все поля","Только видимые","Только с атрибутом name, не отключённые; из флажков — отмеченные","Только text"]', 2, 'Поля без имени и disabled в данные не попадают, а кнопка — только если нажата именно она.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 1, 'Почему нельзя полагаться только на клиентскую валидацию?', '["Запрос можно отправить в обход формы, поэтому сервер обязан проверять заново","Браузеры её не поддерживают","Она слишком медленная","Она запрещена"]', 0, 'Клиентская проверка — удобство для пользователя, а не защита.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 2, 'Какой атрибут куки скрывает её от JavaScript?', '["Secure","SameSite","Path","HttpOnly"]', 3, 'HttpOnly запрещает чтение через document.cookie — поэтому идентификатор сессии хранят именно так.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 3, 'В чём особенность localStorage?', '["Асинхронный и без ограничений","Синхронный, хранит строки, квота около 5 МБ, данные доступны любому скрипту страницы","Очищается при закрытии вкладки","Отправляется с каждым запросом"]', 1, 'Для больших объёмов и запросов применяют IndexedDB, а секреты в localStorage не хранят.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 4, 'Что делает history.pushState?', '["Перезагружает страницу","Удаляет историю","Добавляет запись в историю и меняет адрес без перезагрузки","Отправляет запрос на сервер"]', 2, 'Когда пользователь жмёт «назад», срабатывает событие popstate — на нём строят маршрутизаторы одностраничных приложений.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 18, 'theory', 'Квиз: сеть в браузере');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 0, 'Когда промис fetch отклоняется?', '["При любом коде ответа 4xx и 5xx","Только при сетевой ошибке — ответ 404 или 500 считается успешно полученным","Только при коде 500","Никогда"]', 1, 'Успешность ответа проверяют сами по res.ok или res.status.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 1, 'Что произойдёт, если вызвать res.json() дважды у одного ответа?', '["Вернётся тот же результат","Запрос повторится","Тело станет пустой строкой","Второй вызов бросит ошибку — тело читается один раз; копию делают через clone()"]', 3, 'Тело — поток, который можно прочитать однократно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 2, 'Как отменить запрос fetch?', '["Передать signal от AbortController и вызвать abort()","res.stop()","Закрыть вкладку","Вызвать clearTimeout"]', 0, 'Промис отклоняется ошибкой AbortError; для таймаута есть AbortSignal.timeout(мс).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 3, 'Зачем браузер отправляет preflight-запрос OPTIONS?', '["Чтобы проверить скорость сети","Чтобы загрузить кеш","Чтобы спросить сервер, разрешены ли метод и заголовки междоменного запроса, до отправки настоящего","Чтобы сжать тело"]', 2, 'Простые запросы идут сразу, а непростые (например, с JSON и своими заголовками) требуют предварительной проверки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 4, 'Чем WebSocket отличается от Server-Sent Events?', '["WebSocket односторонний, SSE двусторонний","Они одинаковы","SSE работает только по UDP","WebSocket двусторонний и сам не переподключается, SSE односторонний (сервер → клиент) и переподключается автоматически"]', 3, 'SSE — обычный HTTP-поток текста с автоматическим Last-Event-ID; WebSocket — отдельный протокол после Upgrade.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 19, 'theory', 'Квиз: воркеры и PWA');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 0, 'Что нельзя передать в postMessage воркеру?', '["Дату","Map и Set","Массив байтов","Функцию или DOM-элемент"]', 3, 'Структурное клонирование не умеет функции и элементы страницы; даты, коллекции и циклические ссылки поддерживаются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 1, 'Что делает список transfer при postMessage?', '["Передаёт владение буфером: у отправителя он становится пустым","Копирует буфер быстрее","Сжимает данные","Шифрует сообщение"]', 0, 'Перенос не копирует память, а отдаёт буфер другому потоку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 2, 'Почему новая версия Service Worker может оставаться в состоянии waiting?', '["Ошибка в коде","Нет интернета","Старая версия ещё управляет открытыми вкладками","Закончилась квота"]', 2, 'Пока вкладки управляются старой версией, новая ждёт; skipWaiting ускоряет переход, но может смешать версии.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 3, 'Какая стратегия подходит для файлов с хешем в имени, которые никогда не меняются?', '["Network Only","Cache First","Network First","Всегда обновлять"]', 1, 'Если содержимое определяется именем, безопаснее и быстрее всегда брать из кеша.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 4, 'Зачем при activate удаляют старые кеши?', '["Чтобы освободить место и не смешивать версии файлов","Чтобы обновить manifest","Чтобы включить HTTPS","Это делает браузер сам"]', 0, 'Имя кеша включает версию; без очистки устаревшие хранилища копятся на диске.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 20, 'theory', 'Квиз: производительность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 0, 'По какому показателю оценивают основные веб-показатели?', '["По среднему","По лучшему замеру","По 75-му процентилю реальных пользователей","По одному лабораторному запуску"]', 2, 'Среднее скрывает медленных пользователей, а один запуск шумен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 1, 'Какая задача считается долгой (long task)?', '["Длиннее 50 мс","Длиннее 5 мс","Длиннее 500 мс","Любая асинхронная"]', 0, 'Пока выполняется задача длиннее 50 мс, страница не реагирует на ввод.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 2, 'Что вызывает «молотилку раскладки»?', '["Использование transform","Чередование записи стилей и чтения размеров в цикле","Ленивая загрузка","Атрибут defer"]', 1, 'Чтение размеров после записи заставляет браузер пересчитать раскладку немедленно; сначала читают всё, потом пишут.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 3, 'Зачем нужна виртуализация длинного списка?', '["Чтобы сжать данные","Чтобы ускорить сеть","Чтобы убрать сортировку","Чтобы держать в документе только видимые строки"]', 3, 'Общую высоту имитируют пустым блоком, а по прокрутке вычисляют диапазон индексов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 4, 'Что мешает странице попасть в bfcache?', '["Обработчик unload и Cache-Control: no-store","Заголовок immutable","Атрибут loading=lazy","Brotli"]', 0, 'Кеш переходов не сохраняет страницы, которые не могут безопасно «заморозиться».');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 21, 'theory', 'Квиз: Node.js изнутри');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 0, 'Что выполняется раньше после текущего обратного вызова?', '["process.nextTick и затем микрозадачи промисов","setTimeout(…, 0)","setImmediate","Все одновременно"]', 0, 'Между обратными вызовами цикл опустошает очередь nextTick, затем микрозадачи; повторяет, пока обе пусты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 1, 'Что из этого выполняется в пуле потоков libuv?', '["Сетевые сокеты","Исполнение JavaScript","Таймеры","Файловые операции, DNS lookup, zlib"]', 3, 'Сокеты используют механизмы ядра (epoll, kqueue); файлы, dns.lookup, zlib и часть crypto — пул, по умолчанию четыре потока.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 2, 'Что делает поле exports в package.json?', '["Список файлов для публикации","Устанавливает зависимости","Задаёт публичные точки входа пакета по условиям; не перечисленное закрыто","Включает TypeScript"]', 2, 'Кроме точек входа, перечисленных в exports, остальные файлы пакета нельзя подключить снаружи.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 3, 'Какой код выхода у процесса, завершённого сигналом SIGTERM (номер 15)?', '["0","143","15","255"]', 1, 'Принято считать 128 + номер сигнала: 128 + 15 = 143.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 4, 'Как правильно завершать сервис по SIGTERM?', '["Сразу вызвать process.exit()","Игнорировать сигнал","Перезапустить процесс","Перестать принимать подключения, дождаться текущих запросов, закрыть ресурсы, выйти — в пределах таймаута"]', 3, 'Корректное завершение не обрывает запросы; повторный сигнал или таймаут — повод выйти принудительно.');
